<script setup lang="ts">
/**
 * A colour field with a hex entry and a picker (`design/components/color-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/color-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, provide, ref, useId, useTemplateRef } from 'vue'

import * as zag from '@zag-js/color-picker'
import { normalizeProps, useMachine } from '@zag-js/vue'

import {
  COLOR_INPUT_REST,
  agentMember,
  composingKey,
  mergeParts,
  useDirection,
} from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/color-input.module.css'
import a11y from '@polymorph/recipes/conventions/a11y.module.css'
import Input from './Input.vue'
import Popover from '../overlays/Popover.vue'

export interface ColorInputMessages {
  plane?: string
  planeValue?: (saturation: number, brightness: number) => string
  hue?: string
  alpha?: string
  railValue?: (name: string, value: number) => string
}

export interface ColorInputProps {
  /**
   * Enables the alpha channel: the alpha rail, the eight-digit hex and the checker.
   */
  alpha?: boolean
  ariaDescribedby?: string
  /**
   * Set by FormField. Set it directly only when there is no visible label.
   */
  ariaLabel?: string
  ariaLabelledby?: string
  ariaRequired?: boolean
  /**
   * Opens the picker on mount, for galleries and tests. Screens let the user open it.
   */
  defaultOpen?: boolean
  defaultValue?: string
  disabled?: boolean
  id?: string
  invalid?: boolean
  /**
   * The picker's sliders' names and value texts in the host's words.
   */
  messages?: ColorInputMessages
  /**
   * Serializes the hex through a hidden input.
   */
  name?: string
  /**
   * Names the swatch button and the popover, for example "Choose accent colour".
   */
  pickerLabel: string
  size?: 'sm' | 'md' | 'lg'
  /**
   * Lowercase hex: `#rrggbb`, or `#rrggbbaa` with `alpha`.
   */
  value?: string
}

defineOptions({ name: 'ColorInput', inheritAttrs: false })

const props = withDefaults(defineProps<ColorInputProps>(), {
  alpha: false,
  ariaRequired: undefined,
  defaultOpen: undefined,
  disabled: false,
  invalid: false,
  size: 'md',
})
const emit = defineEmits<{ change: [value: string] }>()
const uid = useId()
provide('polymorph:identity', 'color-input')
const borrowed: { element?: () => Element | null | undefined } = {}
provide('polymorph:borrowed', borrowed)
const mirror = ref(null as string | null)
const draft = ref(null as string | null)
const hexField = useTemplateRef<HTMLElement>('hexField')
const root = useTemplateRef<HTMLElement>('root')
const say = computed(() => ({
  plane: 'saturation and brightness',
  planeValue: (saturation: number, brightness: number) =>
    `saturation ${saturation}, brightness ${brightness}`,
  hue: 'hue',
  alpha: 'alpha',
  railValue: (name: string, value: number) => `${name} ${value}`,
  ...props.messages,
}))
const parseHex = computed(
  () => (text: string) =>
    ((bare: string) =>
      /^([0-9a-f]{3}|[0-9a-f]{6}|[0-9a-f]{8})$/i.test(bare)
        ? ((parsed) => (props.alpha ? parsed : parsed.withChannelValue('alpha', 1)))(
            zag.parse(`#${bare}`).toFormat('hsba'),
          )
        : null)(text.trim().replace(/^#/, '')),
)
const formatHex = computed(
  () => (shown: { toString: (format: 'hex' | 'hexa') => string }) =>
    shown.toString(props.alpha ? 'hexa' : 'hex').toLowerCase(),
)
const kept = computed(() =>
  mirror.value === null
    ? (parseHex.value(props.defaultValue ?? COLOR_INPUT_REST) ?? parseHex.value(COLOR_INPUT_REST))!
    : zag.parse(mirror.value),
)
const controlled = computed(() => (props.value === undefined ? null : parseHex.value(props.value)))
const color = computed(() =>
  controlled.value !== null && formatHex.value(controlled.value) !== formatHex.value(kept.value)
    ? controlled.value
    : kept.value,
)
const hex = computed(() => formatHex.value(color.value))
const setColor = computed(
  () =>
    (next: {
      toFormat: (format: 'hsba') => { toString: (format: 'hsba' | 'hex' | 'hexa') => string }
    }) =>
      ((normalized) => (
        (mirror.value = normalized.toString('hsba')),
        emit('change', formatHex.value(normalized))
      ))(next.toFormat('hsba')),
)
const commitDraft = computed(
  () => () =>
    draft.value !== null &&
    ((next) => ((draft.value = null), next !== null && setColor.value(next)))(
      parseHex.value(draft.value),
    ),
)
const toDraft = computed(
  () => (text: string) =>
    text
      .replace(/#/g, '')
      .trim()
      .slice(0, props.alpha ? 8 : 6),
)
const documentDirection = useDirection(() => root.value)
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    value: color.value,
    format: 'hsba' as const,
    inline: true,
    disabled: props.disabled,
    onValueChange: (details) => {
      setColor.value(details.value)
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const held = computed(() => (api.value.dragging ? service.context.get('activeId') : null))
const fills = computed(() => ({
  hue: (
    api.value.getChannelSliderTrackProps({ channel: 'hue' }).style as { backgroundImage?: string }
  ).backgroundImage,
  alpha: (
    api.value.getChannelSliderTrackProps({ channel: 'alpha' }).style as { backgroundImage?: string }
  ).backgroundImage,
}))
const fromRange = computed(
  () => (channel: 'saturation' | 'brightness' | 'hue' | 'alpha', event: Event) =>
    api.value.setChannelValue(channel, Number((event.target as HTMLInputElement).value)),
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'ColorInput',
    element: () => hexField.value?.querySelector('input'),
    state: () => ({ value: hex.value, disabled: props.disabled, invalid: props.invalid }),
    actions: {
      set: {
        argument: 'text',
        run: (value) =>
          (() => {
            const next = parseHex.value(value)
            if (next === null) throw new Error(`"${value}" is not a hex colour.`)
            draft.value = null
            setColor.value(next)
          })(),
      },
    },
    withholds: () => [root.value, borrowed.element?.()],
  })
  release1 = () => {
    ran()
  }
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
</script>

<template>
  <span
    ref="root"
    :class="styles.root"
    :data-size="size"
    :data-disabled="disabled ? '' : undefined"
    :data-invalid="invalid ? '' : undefined"
    :data-alpha="alpha ? '' : undefined"
    data-member="color-input"
  >
    <Popover :label="pickerLabel" :defaultOpen="defaultOpen" align="start">
      <template #trigger>
        <!-- trigger -->
        <button :class="styles.swatch" type="button" :disabled="disabled" :aria-label="pickerLabel">
          <span
            :class="styles.swatchFill"
            :style="{ '--pm-color-input-swatch': color.toString('css') }"
          />
        </button>
      </template>
      <template #default>
        <!-- picker -->
        <div :class="styles.picker">
          <!-- plane -->
          <div
            v-bind="mergeParts(api.getAreaBackgroundProps(), api.getAreaProps())"
            :class="styles.plane"
          >
            <span
              v-bind="api.getAreaThumbProps()"
              :class="styles.thumb"
              :tabindex="undefined"
              :role="undefined"
              :aria-label="undefined"
              :aria-valuenow="undefined"
              :aria-valuemin="undefined"
              :aria-valuemax="undefined"
              :aria-valuetext="undefined"
              :aria-roledescription="undefined"
              :aria-orientation="undefined"
              :aria-disabled="undefined"
              :data-state="held === 'area' ? 'dragging' : undefined"
            >
              <input
                :class="a11y.visuallyHidden"
                type="range"
                :min="color.getChannelRange('saturation').minValue"
                :max="color.getChannelRange('saturation').maxValue"
                :step="color.getChannelRange('saturation').step"
                :value="color.getChannelValue('saturation')"
                :disabled="disabled"
                :aria-label="say.plane"
                :aria-valuetext="
                  say.planeValue(
                    color.getChannelValue('saturation'),
                    color.getChannelValue('brightness'),
                  )
                "
                @input="fromRange('saturation', $event)"
              />
              <input
                :class="a11y.visuallyHidden"
                type="range"
                :min="color.getChannelRange('brightness').minValue"
                :max="color.getChannelRange('brightness').maxValue"
                :step="color.getChannelRange('brightness').step"
                :value="color.getChannelValue('brightness')"
                :disabled="disabled"
                tabindex="-1"
                aria-hidden="true"
                @input="fromRange('brightness', $event)"
              />
            </span>
          </div>
          <!-- rail -->
          <div
            v-bind="api.getChannelSliderProps({ channel: 'hue' })"
            :class="styles.rail"
            :data-checker="undefined"
          >
            <span
              :class="styles.railFill"
              :style="{ backgroundImage: fills.hue }"
              aria-hidden="true"
            />
            <span
              v-bind="api.getChannelSliderThumbProps({ channel: 'hue' })"
              :class="styles.thumb"
              :tabindex="undefined"
              :role="undefined"
              :aria-label="undefined"
              :aria-valuenow="undefined"
              :aria-valuemin="undefined"
              :aria-valuemax="undefined"
              :aria-valuetext="undefined"
              :aria-roledescription="undefined"
              :aria-orientation="undefined"
              :aria-disabled="undefined"
              :data-state="held === 'hue' ? 'dragging' : undefined"
            >
              <input
                :class="a11y.visuallyHidden"
                type="range"
                :min="color.getChannelRange('hue').minValue"
                :max="color.getChannelRange('hue').maxValue"
                :step="color.getChannelRange('hue').step"
                :value="color.getChannelValue('hue')"
                :disabled="disabled"
                :aria-label="say.hue"
                :aria-valuetext="say.railValue(say.hue, color.getChannelValue('hue'))"
                @input="fromRange('hue', $event)"
              />
            </span>
          </div>
          <!-- rail -->
          <div
            v-if="alpha"
            v-bind="api.getChannelSliderProps({ channel: 'alpha' })"
            :class="styles.rail"
            data-checker=""
          >
            <span
              :class="styles.railFill"
              :style="{ backgroundImage: fills.alpha }"
              aria-hidden="true"
            />
            <span
              v-bind="api.getChannelSliderThumbProps({ channel: 'alpha' })"
              :class="styles.thumb"
              :tabindex="undefined"
              :role="undefined"
              :aria-label="undefined"
              :aria-valuenow="undefined"
              :aria-valuemin="undefined"
              :aria-valuemax="undefined"
              :aria-valuetext="undefined"
              :aria-roledescription="undefined"
              :aria-orientation="undefined"
              :aria-disabled="undefined"
              :data-state="held === 'alpha' ? 'dragging' : undefined"
            >
              <input
                :class="a11y.visuallyHidden"
                type="range"
                :min="color.getChannelRange('alpha').minValue"
                :max="color.getChannelRange('alpha').maxValue"
                :step="color.getChannelRange('alpha').step"
                :value="color.getChannelValue('alpha')"
                :disabled="disabled"
                :aria-label="say.alpha"
                :aria-valuetext="say.railValue(say.alpha, color.getChannelValue('alpha'))"
                @input="fromRange('alpha', $event)"
              />
            </span>
          </div>
        </div>
      </template>
    </Popover>
    <span
      ref="hexField"
      :class="styles.field"
      @keydown="$event.key === 'Enter' && !composingKey($event) && commitDraft()"
    >
      <Input
        :value="draft ?? hex.replace(/^#/, '')"
        prefix="#"
        :size="size"
        :disabled="disabled"
        :invalid="invalid"
        :id="id"
        autoComplete="off"
        :aria-label="ariaLabel"
        :aria-labelledby="ariaLabelledby"
        :aria-describedby="ariaDescribedby"
        :aria-required="ariaRequired"
        @change="draft = toDraft($event)"
        @blur="commitDraft()"
      />
    </span>
    <input v-if="name !== undefined" type="hidden" :name="name" :value="hex" />
  </span>
</template>
